// PATCH contract checks.
const fresh = (displayName = 'before', tags = ['old']) =>
  new ProfileService({ displayName, tags: [...tags] });
const invalidProfile = { name: 'Error', message: 'invalid profile' };

// Asserts the input is rejected and storage is byte-for-byte unchanged.
function rejects(input, service = fresh()) {
  const before = structuredClone(service.profile);
  assert.throws(() => service.patch(input), invalidProfile);
  assert.deepEqual(service.profile, before);
}

// Empty object is a valid no-op.
{
  const s = fresh();
  assert.deepEqual(s.patch({}), { displayName: 'before', tags: ['old'] });
}

// Absent fields keep stored values; the stored profile object is returned.
{
  const s = fresh();
  const result = s.patch({ displayName: '  Ada  ' });
  assert.equal(result, s.profile);
  assert.deepEqual(result, { displayName: 'Ada', tags: ['old'] });
  assert.deepEqual(s.patch({ displayName: 'Ada', tags: ['x'] }), { displayName: 'Ada', tags: ['x'] });
}

// null clears displayName; null or [] clears tags.
{
  const s = fresh();
  assert.deepEqual(s.patch({ displayName: null }), { displayName: null, tags: ['old'] });
  assert.deepEqual(s.patch({ tags: null }), { displayName: null, tags: [] });
  s.patch({ tags: ['a'] });
  assert.deepEqual(s.patch({ tags: [] }), { displayName: null, tags: [] });
}

// displayName: trimmed, length 1..40 after trimming.
{
  const s = fresh();
  assert.equal(s.patch({ displayName: ` ${'a'.repeat(40)} ` }).displayName, 'a'.repeat(40));
  rejects({ displayName: '' }, s);
  rejects({ displayName: '   ' }, s);
  rejects({ displayName: 'a'.repeat(41) }, s);
  rejects({ displayName: ` ${'a'.repeat(41)} ` }, s);
}

// tags: at most five distinct non-empty strings, trimmed, each at most 12 chars.
{
  const s = fresh();
  assert.deepEqual(s.patch({ tags: [' a ', 'b', 'a'.repeat(12)] }).tags, ['a', 'b', 'a'.repeat(12)]);
  assert.deepEqual(s.patch({ tags: ['a', 'b', 'c', 'd', 'e'] }).tags, ['a', 'b', 'c', 'd', 'e']);
  rejects({ tags: ['a', 'b', 'c', 'd', 'e', 'f'] }, s);
  rejects({ tags: ['a', ' a '] }, s); // duplicate after trimming
  rejects({ tags: ['  '] }, s); // empty after trimming
  rejects({ tags: ['a'.repeat(13)] }, s);
  rejects({ tags: [` ${'a'.repeat(13)} `] }, s);
  rejects({ tags: [1] }, s); // no numeric coercion
  rejects({ tags: ['a', null] }, s);
  rejects({ tags: [, 'a'] }, s); // hole
  rejects({ tags: 'a' }, s);
  rejects({ tags: {} }, s);
}

// No numeric coercion for displayName; undefined counts as a present, invalid value.
{
  const s = fresh();
  rejects({ displayName: 0 }, s);
  rejects({ displayName: 5 }, s);
  rejects({ displayName: undefined }, s);
  rejects({ tags: undefined }, s);
  rejects({ displayName: {} }, s);
  rejects({ displayName: ['a'] }, s);
}

// Top-level input must be a plain object (Object.prototype or null prototype).
{
  const s = fresh();
  for (const bad of [
    null, undefined, 'x', 1, true, [], [{}], () => {},
    Object.create({ displayName: 'x' }), Object.create(Array.prototype),
  ]) {
    rejects(bad, s);
  }
  const nullProto = Object.create(null);
  nullProto.displayName = 'Grace';
  assert.equal(s.patch(nullProto).displayName, 'Grace');
}

// Unknown keys are rejected, including symbol, non-enumerable, and own __proto__ keys.
{
  const s = fresh();
  rejects({ displayName: 'a', extra: 1 }, s);
  rejects({ [Symbol('x')]: 1 }, s);
  rejects(Object.defineProperty({}, 'hidden', { value: 1, enumerable: false }), s);
  rejects(JSON.parse('{"__proto__": {"x": 1}}'), s);
}

// Accessor properties are rejected, and their getters are never invoked.
{
  const s = fresh();
  let calls = 0;
  const getter = () => { calls += 1; return 'x'; };
  rejects(Object.defineProperty({}, 'displayName', { get: getter, enumerable: true }), s);
  rejects(Object.defineProperty({}, 'tags', { get: () => ['a'], enumerable: true }), s);
  rejects(Object.defineProperty({ tags: [] }, 'displayName', { get: getter, enumerable: true }), s);
  assert.equal(calls, 0);
}

// A failing field leaves storage unchanged, even when another field was valid.
{
  const s = fresh();
  rejects({ displayName: 'new', tags: ['a', 'a'] }, s);
  rejects({ displayName: 'new', tags: 'bad' }, s);
}

// Input is not mutated, and stored tags are not the caller's array.
{
  const s = fresh();
  const input = { displayName: ' Ada ', tags: [' a ', 'b'] };
  const original = structuredClone(input);
  const result = s.patch(input);
  assert.deepEqual(input, original);
  assert.deepEqual(result, { displayName: 'Ada', tags: ['a', 'b'] });
  assert.notEqual(result.tags, input.tags);
  input.tags[0] = 'mutated';
  input.tags.push('z');
  assert.deepEqual(s.profile.tags, ['a', 'b']);
}

