import { ProfilePatch } from './types';

const MAX_DISPLAY_NAME_LENGTH = 40;
const MAX_TAG_COUNT = 5;
const MAX_TAG_LENGTH = 12;

function invalid(): never {
  throw new Error('invalid profile');
}

function parseDisplayName(value: unknown): string | null {
  if (value === null) return null;
  if (typeof value !== 'string') invalid();
  const trimmed = value.trim();
  if (trimmed.length < 1 || trimmed.length > MAX_DISPLAY_NAME_LENGTH) invalid();
  return trimmed;
}

// Builds a fresh array of trimmed tags. The caller's array is never stored.
function parseTags(value: unknown): string[] {
  if (value === null) return [];
  if (!Array.isArray(value) || value.length > MAX_TAG_COUNT) invalid();
  const tags: string[] = [];
  const seen = new Set<string>();
  for (let i = 0; i < value.length; i++) {
    // Descriptors are read instead of values so getters never run. A hole has
    // no own property, and an accessor has no `value`; both fail the checks below.
    const item = Object.getOwnPropertyDescriptor(value, String(i));
    if (item === undefined) invalid();
    const raw: unknown = item.value;
    if (typeof raw !== 'string') invalid();
    const trimmed = raw.trim();
    if (trimmed.length < 1 || trimmed.length > MAX_TAG_LENGTH) invalid();
    if (seen.has(trimmed)) invalid();
    seen.add(trimmed);
    tags.push(trimmed);
  }
  return tags;
}

export function parseProfile(input: unknown): ProfilePatch {
  if (typeof input !== 'object' || input === null || Array.isArray(input)) invalid();
  const proto = Object.getPrototypeOf(input);
  if (proto !== Object.prototype && proto !== null) invalid();
  for (const key of Reflect.ownKeys(input)) {
    if (key !== 'displayName' && key !== 'tags') invalid();
  }
  let displayName: ProfilePatch['displayName'] = { kind: 'keep' };
  let tags: ProfilePatch['tags'] = { kind: 'keep' };
  // Same as above: read descriptors so getters never run. An accessor's
  // `value` is undefined, which fails the type checks.
  const displayNameDesc = Object.getOwnPropertyDescriptor(input, 'displayName');
  if (displayNameDesc !== undefined) {
    displayName = { kind: 'set', value: parseDisplayName(displayNameDesc.value) };
  }
  const tagsDesc = Object.getOwnPropertyDescriptor(input, 'tags');
  if (tagsDesc !== undefined) {
    tags = { kind: 'set', value: parseTags(tagsDesc.value) };
  }
  return { displayName, tags };
}
